// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITetherToken {
    function issue(uint amount) external;
    function redeem(uint amount) external;
    function totalSupply() external view returns (uint);
    function balanceOf(address who) external view returns (uint);
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);
    ITetherToken token;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = ITetherToken(TARGET);
        owner = token.owner();
        vm.label(TARGET, "TetherToken");
        vm.label(owner, "Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        vm.startPrank(owner);
        uint256 issueAmount = type(uint256).max / 2;
        token.issue(issueAmount);
        vm.stopPrank();
        uint256 totalSupply = token.totalSupply();
        uint256 ownerBalance = token.balanceOf(owner);
        assertGt(totalSupply, ownerBalance);
        assertTrue(totalSupply != ownerBalance, "Logic Exploit Failed: Value unchanged");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
